"use client";

import Link from "next/link";
import { FormEvent, useEffect, useMemo, useState } from "react";
import { confirmSignUp, resendSignUpCode, signUp } from "aws-amplify/auth";
import {
  BarChart3,
  BriefcaseBusiness,
  Eye,
  Lock,
  Mail,
  ShieldCheck,
  Sparkles,
  User,
  UsersRound,
  Workflow,
} from "lucide-react";
import { getCognitoAuthorizeUrl } from "@/services/auth";

type Role = "candidate" | "recruiter";

export default function SignupPage() {
  const [step, setStep] = useState<"signup" | "verify">("signup");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [code, setCode] = useState("");
  const [acceptedTerms, setAcceptedTerms] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  const [form, setForm] = useState({
    firstName: "",
    lastName: "",
    email: "",
    password: "",
    confirmPassword: "",
    tenantId: "",
    role: "candidate" as Role,
  });

  useEffect(() => {
    const role = new URLSearchParams(window.location.search).get("role");
    if (role === "candidate" || role === "recruiter") {
      setForm((previous) => ({ ...previous, role }));
    }
  }, []);

  const helperText = useMemo(() => {
    if (form.role === "recruiter") {
      return "Recruiter access may require admin approval after signup.";
    }
    return "Candidate accounts can upload resumes and apply to jobs.";
  }, [form.role]);

  const onSignup = async (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setError(null);
    setNotice(null);
    setLoading(true);

    try {
      if (form.password !== form.confirmPassword) {
        throw new Error("Password and confirm password do not match");
      }
      if (!acceptedTerms) {
        throw new Error("Please accept the terms before creating an account");
      }

      const fullName = `${form.firstName.trim()} ${form.lastName.trim()}`.trim();
      const response = await signUp({
        username: form.email.trim().toLowerCase(),
        password: form.password,
        options: {
          userAttributes: {
            email: form.email.trim().toLowerCase(),
            name: fullName,
            "custom:role": form.role,
            "custom:tenantId": form.tenantId.trim(),
          },
          clientMetadata: {
            role: form.role,
          },
        },
      });

      if (response.nextStep.signUpStep === "CONFIRM_SIGN_UP") {
        setStep("verify");
        setNotice("Verification code sent to your email.");
      } else {
        setNotice("Signup completed. Redirecting to sign in...");
        window.location.assign(getCognitoAuthorizeUrl(form.email));
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "Signup failed");
    } finally {
      setLoading(false);
    }
  };

  const onVerify = async (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setError(null);
    setNotice(null);
    setLoading(true);

    try {
      await confirmSignUp({
        username: form.email.trim().toLowerCase(),
        confirmationCode: code.trim(),
      });
      localStorage.setItem("auth_notice", "signup_verified");
      window.location.assign(getCognitoAuthorizeUrl(form.email));
    } catch (err) {
      setError(err instanceof Error ? err.message : "Verification failed");
    } finally {
      setLoading(false);
    }
  };

  const onResendCode = async () => {
    setError(null);
    setNotice(null);
    setLoading(true);
    try {
      await resendSignUpCode({
        username: form.email.trim().toLowerCase(),
      });
      setNotice("Verification code resent.");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Could not resend code");
    } finally {
      setLoading(false);
    }
  };

  return (
    <main className="min-h-screen bg-[#f4f4f5] px-3 py-4 text-[#171717] sm:px-5">
      <div className="mx-auto grid min-h-[calc(100vh-2rem)] max-w-6xl overflow-hidden bg-white shadow-sm lg:grid-cols-[0.72fr_1fr]">
        <section className="relative hidden flex-col justify-between overflow-hidden bg-[#08090b] px-12 py-9 text-white lg:flex">
          <div>
            <div className="flex items-center gap-3">
              <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-white/10 ring-1 ring-white/10">
                <BriefcaseBusiness className="h-5 w-5" />
              </div>
              <div>
                <p className="text-[15px] font-black uppercase tracking-[0.18em]">
                  TalentFlow AI
                </p>
                <p className="mt-1 text-xs font-medium text-zinc-400">
                  Hiring Intelligence Platform
                </p>
              </div>
            </div>

            <div className="mt-10 inline-flex items-center gap-2 rounded-full border border-white/10 bg-white/[0.04] px-4 py-2 text-xs font-semibold text-blue-100">
              <Sparkles className="h-3.5 w-3.5 text-blue-300" />
              Smarter hiring, faster decisions
            </div>

            <h1 className="mt-8 max-w-sm text-[42px] font-black leading-[1.08] tracking-[-0.02em] text-white">
              Join the Future of Hiring
            </h1>
            <p className="mt-6 max-w-xs text-[15px] font-medium leading-7 text-zinc-400">
              Create your account and start making smarter hiring decisions
              powered by AI.
            </p>
          </div>

          <div className="grid grid-cols-3 gap-3">
            <FeatureCard
              icon={UsersRound}
              title="Candidate Insights"
              description="Review profiles with clarity and speed."
            />
            <FeatureCard
              icon={BarChart3}
              title="Hiring Analytics"
              description="Track pipeline performance in real time."
            />
            <FeatureCard
              icon={Workflow}
              title="ATS Workflow"
              description="Move candidates through every stage."
            />
          </div>
        </section>

        <section className="flex items-center justify-center bg-[#fafafa] px-5 py-8 sm:px-8">
          <div className="w-full max-w-[560px] rounded-[22px] border border-zinc-200 bg-white px-8 py-8 shadow-[0_18px_48px_rgba(15,23,42,0.08)] sm:px-9">
            <h2 className="text-[28px] font-black tracking-[-0.02em] text-zinc-950">
              {step === "signup" ? "Create your account" : "Verify your email"}
            </h2>
            <p className="mt-2 text-[15px] text-zinc-500">
              {step === "signup"
                ? "Sign up to access your hiring dashboard."
                : "Enter the verification code sent to your email."}
            </p>

            {notice ? (
              <p className="mt-5 rounded-lg border border-emerald-200 bg-emerald-50 px-3 py-2 text-sm text-emerald-700">
                {notice}
              </p>
            ) : null}
            {error ? (
              <p className="mt-5 rounded-lg border border-rose-200 bg-rose-50 px-3 py-2 text-sm text-rose-700">
                {error}
              </p>
            ) : null}

            {step === "signup" ? (
              <form onSubmit={onSignup} className="mt-7 space-y-4">
                <div className="grid gap-3 sm:grid-cols-2">
                  <TextInput
                    label="First Name"
                    icon={User}
                    value={form.firstName}
                    placeholder="John"
                    onChange={(value) =>
                      setForm((p) => ({ ...p, firstName: value }))
                    }
                    required
                  />
                  <TextInput
                    label="Last Name"
                    icon={User}
                    value={form.lastName}
                    placeholder="Doe"
                    onChange={(value) =>
                      setForm((p) => ({ ...p, lastName: value }))
                    }
                    required
                  />
                </div>

                <TextInput
                  label="Email"
                  icon={Mail}
                  type="email"
                  value={form.email}
                  placeholder="admin@test.com"
                  onChange={(value) => setForm((p) => ({ ...p, email: value }))}
                  required
                />

                <PasswordInput
                  label="Password"
                  value={form.password}
                  visible={showPassword}
                  onToggle={() => setShowPassword((value) => !value)}
                  onChange={(value) =>
                    setForm((p) => ({ ...p, password: value }))
                  }
                />

                <PasswordInput
                  label="Confirm Password"
                  value={form.confirmPassword}
                  visible={showConfirmPassword}
                  onToggle={() => setShowConfirmPassword((value) => !value)}
                  onChange={(value) =>
                    setForm((p) => ({ ...p, confirmPassword: value }))
                  }
                />

                <div>
                  <p className="text-xs font-semibold text-zinc-900">
                    Choose your workspace
                  </p>
                  <div className="mt-2 grid gap-3 sm:grid-cols-2">
                    <RoleCard
                      active={form.role === "recruiter"}
                      title="Recruiter"
                      description="Post jobs, review candidates, and manage hiring pipelines."
                      onClick={() =>
                        setForm((p) => ({ ...p, role: "recruiter" }))
                      }
                    />
                    <RoleCard
                      active={form.role === "candidate"}
                      title="Candidate"
                      description="Apply to roles, upload resumes, and track applications."
                      onClick={() =>
                        setForm((p) => ({ ...p, role: "candidate" }))
                      }
                    />
                  </div>
                </div>

                <TextInput
                  label={form.role === "recruiter" ? "Company ID" : "Talent Pool ID"}
                  icon={ShieldCheck}
                  value={form.tenantId}
                  placeholder={form.role === "recruiter" ? "techcorp" : "public"}
                  onChange={(value) =>
                    setForm((p) => ({ ...p, tenantId: value }))
                  }
                  required
                />
                <p className="-mt-2 text-xs text-zinc-500">{helperText}</p>

                <label className="flex items-center gap-2 text-xs text-zinc-500">
                  <input
                    type="checkbox"
                    checked={acceptedTerms}
                    onChange={(event) => setAcceptedTerms(event.target.checked)}
                    className="h-3.5 w-3.5 rounded border-zinc-300 accent-zinc-950"
                  />
                  <span>
                    I agree to the{" "}
                    <span className="font-semibold text-zinc-800">Terms of Service</span>
                    and{" "}
                    <span className="font-semibold text-zinc-800">Privacy Policy</span>
                  </span>
                </label>

                <button
                  className="h-12 w-full rounded-xl bg-[#151515] text-sm font-black text-white shadow-[0_10px_18px_rgba(0,0,0,0.18)] transition hover:bg-black disabled:cursor-not-allowed disabled:opacity-60"
                  type="submit"
                  disabled={loading}
                >
                  {loading ? "Creating Account..." : "Create Account"}
                </button>
              </form>
            ) : (
              <form onSubmit={onVerify} className="mt-7 space-y-4">
                <TextInput
                  label="Verification Code"
                  icon={ShieldCheck}
                  value={code}
                  placeholder="123456"
                  onChange={setCode}
                  required
                />
                <button
                  className="h-12 w-full rounded-xl bg-[#151515] text-sm font-black text-white shadow-[0_10px_18px_rgba(0,0,0,0.18)] transition hover:bg-black disabled:cursor-not-allowed disabled:opacity-60"
                  type="submit"
                  disabled={loading}
                >
                  {loading ? "Verifying..." : "Verify Email"}
                </button>
                <button
                  className="h-11 w-full rounded-xl border border-zinc-200 bg-white text-sm font-semibold text-zinc-900 shadow-sm transition hover:bg-zinc-50 disabled:opacity-60"
                  type="button"
                  disabled={loading}
                  onClick={onResendCode}
                >
                  Resend Code
                </button>
              </form>
            )}

            <p className="mt-5 text-center text-sm text-zinc-500">
              Already have an account?
              <Link
                className="ml-1 font-black text-zinc-950 hover:underline"
                href="/signin"
              >
                Sign In
              </Link>
            </p>
          </div>
        </section>
      </div>
    </main>
  );
}

function RoleCard({
  active,
  title,
  description,
  onClick,
}: {
  active: boolean;
  title: string;
  description: string;
  onClick: () => void;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={`rounded-2xl border p-4 text-left transition ${
        active
          ? "border-zinc-950 bg-zinc-950 text-white shadow-[0_14px_28px_rgba(15,23,42,0.16)]"
          : "border-zinc-200 bg-white text-zinc-900 hover:border-zinc-400"
      }`}
    >
      <span className="flex items-center justify-between gap-3">
        <span className="text-sm font-black">{title}</span>
        <span
          className={`h-3 w-3 rounded-full border ${
            active ? "border-white bg-blue-500" : "border-zinc-300"
          }`}
        />
      </span>
      <span
        className={`mt-2 block text-xs leading-5 ${
          active ? "text-zinc-300" : "text-zinc-500"
        }`}
      >
        {description}
      </span>
    </button>
  );
}

function FeatureCard({
  icon: Icon,
  title,
  description,
}: {
  icon: typeof UsersRound;
  title: string;
  description: string;
}) {
  return (
    <article className="rounded-xl border border-white/10 bg-white/[0.04] p-4">
      <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-[#151922] text-blue-300">
        <Icon className="h-4 w-4" />
      </div>
      <h3 className="mt-4 text-xs font-black leading-4 text-white">{title}</h3>
      <p className="mt-2 text-xs font-semibold leading-5 text-zinc-500">
        {description}
      </p>
    </article>
  );
}

function TextInput({
  label,
  icon: Icon,
  value,
  onChange,
  placeholder,
  type = "text",
  required = false,
}: {
  label: string;
  icon: typeof User;
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  type?: string;
  required?: boolean;
}) {
  return (
    <label className="block text-xs font-semibold text-zinc-900">
      {label}
      <span className="relative mt-2 block">
        <Icon className="pointer-events-none absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-zinc-400" />
        <input
          type={type}
          value={value}
          onChange={(event) => onChange(event.target.value)}
          placeholder={placeholder}
          required={required}
          className="h-11 w-full rounded-xl border border-zinc-200 bg-[#eef4fd] pl-11 pr-3 text-sm text-zinc-800 shadow-sm outline-none transition placeholder:text-zinc-500 focus:border-zinc-400 focus:ring-2 focus:ring-zinc-100"
        />
      </span>
    </label>
  );
}

function PasswordInput({
  label,
  value,
  visible,
  onToggle,
  onChange,
}: {
  label: string;
  value: string;
  visible: boolean;
  onToggle: () => void;
  onChange: (value: string) => void;
}) {
  return (
    <label className="block text-xs font-semibold text-zinc-900">
      {label}
      <span className="relative mt-2 block">
        <Lock className="pointer-events-none absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-zinc-400" />
        <input
          type={visible ? "text" : "password"}
          value={value}
          onChange={(event) => onChange(event.target.value)}
          required
          minLength={8}
          placeholder="••••••••"
          className="h-11 w-full rounded-xl border border-zinc-200 bg-[#eef4fd] pl-11 pr-11 text-sm text-zinc-800 shadow-sm outline-none transition placeholder:text-zinc-500 focus:border-zinc-400 focus:ring-2 focus:ring-zinc-100"
        />
        <button
          type="button"
          onClick={onToggle}
          className="absolute right-3 top-1/2 flex h-7 w-7 -translate-y-1/2 items-center justify-center rounded-md text-zinc-400 hover:bg-white/70 hover:text-zinc-700"
          aria-label={visible ? "Hide password" : "Show password"}
        >
          <Eye className="h-4 w-4" />
        </button>
      </span>
    </label>
  );
}
